from typing import List, Optional, Set
from collections import deque


class Commit:
    """Represents a Git commit."""

    def __init__(self, sha: str, message: str, parents: List[str], timestamp: int):
        self.sha = sha
        self.message = message
        self.parents = parents
        self.timestamp = timestamp

    def __repr__(self):
        return f"Commit(sha='{self.sha}', message='{self.message}')"


class CommitGraph:
    """Manages a graph of Git commits."""

    def __init__(self):
        self._commits: dict[str, Commit] = {}

    def add_commit(self, sha: str, message: str, parents: List[str], timestamp: int) -> Commit:
        """Add a new commit to the graph."""
        # Check if commit already exists
        if sha in self._commits:
            raise ValueError(f"Commit with SHA '{sha}' already exists")

        # Validate parents exist (except for initial commit)
        for parent_sha in parents:
            if parent_sha not in self._commits:
                raise ValueError(f"Parent commit '{parent_sha}' does not exist")

        commit = Commit(sha, message, parents, timestamp)
        self._commits[sha] = commit
        return commit

    def get_commit(self, sha: str) -> Optional[Commit]:
        """Return the Commit object for the given SHA."""
        return self._commits.get(sha)

    def get_history(self, sha: str, max_count: Optional[int] = None) -> List[str]:
        """Return commit history from the given SHA, newest first."""
        if sha not in self._commits:
            return []

        result = []
        visited: Set[str] = set()
        # Priority queue: use negative timestamp for max-heap behavior
        # We'll use a list and sort to simulate priority queue
        to_visit = [self._commits[sha]]

        while to_visit and (max_count is None or len(result) < max_count):
            # Sort by timestamp descending and pick the newest
            to_visit.sort(key=lambda c: c.timestamp, reverse=True)
            current = to_visit.pop(0)

            if current.sha in visited:
                continue

            visited.add(current.sha)
            result.append(current.sha)

            # Add parents to visit list
            for parent_sha in current.parents:
                if parent_sha not in visited and parent_sha in self._commits:
                    to_visit.append(self._commits[parent_sha])

        return result

    def find_common_ancestor(self, sha1: str, sha2: str) -> Optional[str]:
        """Find the most recent common ancestor of two commits."""
        if sha1 not in self._commits or sha2 not in self._commits:
            return None

        # Get all ancestors of sha1
        ancestors1: Set[str] = set()
        queue = deque([sha1])
        while queue:
            current = queue.popleft()
            if current in ancestors1:
                continue
            ancestors1.add(current)
            commit = self._commits.get(current)
            if commit:
                for parent in commit.parents:
                    queue.append(parent)

        # BFS from sha2, find first commit that's in ancestors1
        # Use timestamp-ordered traversal to find most recent
        visited: Set[str] = set()
        to_visit = [self._commits[sha2]]

        while to_visit:
            # Sort by timestamp descending
            to_visit.sort(key=lambda c: c.timestamp, reverse=True)
            current = to_visit.pop(0)

            if current.sha in visited:
                continue

            if current.sha in ancestors1:
                return current.sha

            visited.add(current.sha)

            for parent_sha in current.parents:
                if parent_sha not in visited and parent_sha in self._commits:
                    to_visit.append(self._commits[parent_sha])

        return None

    def get_commits_between(self, ancestor_sha: str, descendant_sha: str) -> List[str]:
        """Return commits reachable from descendant but not from ancestor."""
        if ancestor_sha not in self._commits or descendant_sha not in self._commits:
            return []

        # Get all ancestors of ancestor_sha (including itself)
        ancestor_set: Set[str] = set()
        queue = deque([ancestor_sha])
        while queue:
            current = queue.popleft()
            if current in ancestor_set:
                continue
            ancestor_set.add(current)
            commit = self._commits.get(current)
            if commit:
                for parent in commit.parents:
                    queue.append(parent)

        # BFS from descendant, collect commits not in ancestor_set
        # Topological sort: children before parents
        result = []
        visited: Set[str] = set()
        queue = deque([descendant_sha])

        # Track in-degree for topological sort
        in_degree: dict[str, int] = {}
        reachable: Set[str] = set()

        # First pass: find all reachable commits not in ancestor_set
        temp_queue = deque([descendant_sha])
        while temp_queue:
            current = temp_queue.popleft()
            if current in reachable or current in ancestor_set:
                continue
            reachable.add(current)
            commit = self._commits.get(current)
            if commit:
                for parent in commit.parents:
                    temp_queue.append(parent)

        # Calculate in-degrees within reachable set
        for sha in reachable:
            in_degree[sha] = 0

        for sha in reachable:
            commit = self._commits.get(sha)
            if commit:
                for parent in commit.parents:
                    if parent in reachable:
                        in_degree[parent] = in_degree.get(parent, 0) + 1

        # Topological sort using Kahn's algorithm
        queue = deque([sha for sha in reachable if in_degree.get(sha, 0) == 0])

        while queue:
            # Sort by timestamp for deterministic ordering among same-level commits
            queue_list = sorted(queue, key=lambda s: self._commits[s].timestamp, reverse=True)
            queue.clear()

            current = queue_list[0]
            for item in queue_list[1:]:
                queue.append(item)

            result.append(current)
            commit = self._commits.get(current)
            if commit:
                for parent in commit.parents:
                    if parent in reachable:
                        in_degree[parent] -= 1
                        if in_degree[parent] == 0:
                            queue.append(parent)

        return result

def two_sum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        if target - num in seen:
            return [seen[target - num], i]
        seen[num] = i
    return []

def move_zeroes(nums):
    write = 0
    for read in range(len(nums)):
        if nums[read] != 0:
            nums[write], nums[read] = nums[read], nums[write]
            write += 1
    return nums

def remove_duplicates(nums):
    if not nums:
        return 0
    write = 1
    for read in range(1, len(nums)):
        if nums[read] != nums[write - 1]:
            nums[write] = nums[read]
            write += 1
    return write

def max_subarray(nums):
    best = current = nums[0]
    for num in nums[1:]:
        current = max(num, current + num)
        best = max(best, current)
    return best

def merge_sorted(a, b):
    out = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

def sort_colors(nums):
    low, mid, high = 0, 0, len(nums) - 1
    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1
            mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[mid], nums[high] = nums[high], nums[mid]
            high -= 1
    return nums

def is_anagram(s, t):
    if len(s) != len(t):
        return False
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in t:
        if counts.get(ch, 0) == 0:
            return False
        counts[ch] -= 1
    return True

def group_anagrams(strs):
    groups = {}
    for s in strs:
        key = ''.join(sorted(s))
        groups.setdefault(key, []).append(s)
    result = [sorted(g) for g in groups.values()]
    result.sort(key=lambda g: g[0])
    return result

def first_uniq_char(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for i, ch in enumerate(s):
        if counts[ch] == 1:
            return i
    return -1

def subarray_sum(nums, k):
    count = 0
    running = 0
    seen = {0: 1}
    for num in nums:
        running += num
        count += seen.get(running - k, 0)
        seen[running] = seen.get(running, 0) + 1
    return count

def top_k_frequent(nums, k):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1
    ordered = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return [num for num, _ in ordered[:k]]

def count_pairs(nums, target):
    counts = {}
    pairs = 0
    for num in nums:
        pairs += counts.get(target - num, 0)
        counts[num] = counts.get(num, 0) + 1
    return pairs

def longest_consecutive(nums):
    num_set = set(nums)
    best = 0
    for num in num_set:
        if num - 1 not in num_set:
            length = 1
            while num + length in num_set:
                length += 1
            best = max(best, length)
    return best

def is_isomorphic(s, t):
    if len(s) != len(t):
        return False
    forward, backward = {}, {}
    for a, b in zip(s, t):
        if a in forward and forward[a] != b:
            return False
        if b in backward and backward[b] != a:
            return False
        forward[a] = b
        backward[b] = a
    return True

class MyHashMap:
    def __init__(self, size=1009):
        self.size = size
        self.buckets = [[] for _ in range(size)]

    def _bucket(self, key):
        return self.buckets[key % self.size]

    def put(self, key, value):
        bucket = self._bucket(key)
        for i, (k, _) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return
        bucket.append((key, value))

    def get(self, key):
        for k, v in self._bucket(key):
            if k == key:
                return v
        return -1

    def remove(self, key):
        bucket = self._bucket(key)
        for i, (k, _) in enumerate(bucket):
            if k == key:
                bucket.pop(i)
                return

def run_ops(ops, args):
    m = MyHashMap()
    out = []
    for op, arg in zip(ops, args):
        if op == 'put':
            m.put(arg[0], arg[1])
        elif op == 'get':
            out.append(m.get(arg[0]))
        elif op == 'remove':
            m.remove(arg[0])
    return out

def contains_duplicate(nums):
    seen = set()
    for num in nums:
        if num in seen:
            return True
        seen.add(num)
    return False

def is_happy(n):
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = sum(int(d) ** 2 for d in str(n))
    return n == 1

def distinct_per_window(nums, k):
    if k <= 0 or k > len(nums):
        return []
    counts = {}
    for num in nums[:k]:
        counts[num] = counts.get(num, 0) + 1
    out = [len(counts)]
    for i in range(k, len(nums)):
        counts[nums[i]] = counts.get(nums[i], 0) + 1
        left = nums[i - k]
        counts[left] -= 1
        if counts[left] == 0:
            del counts[left]
        out.append(len(counts))
    return out

def missing_number(nums):
    present = set(nums)
    for candidate in range(len(nums) + 1):
        if candidate not in present:
            return candidate
    return -1

def set_report(a, b):
    sa, sb = set(a), set(b)
    return {
        'union': sorted(sa | sb),
        'intersection': sorted(sa & sb),
        'a_only': sorted(sa - sb),
        'symmetric': sorted(sa ^ sb),
    }

def is_valid(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            stack.append(ch)
    return not stack

class MinStack:
    def __init__(self):
        self.stack = []
        self.mins = []

    def push(self, x):
        self.stack.append(x)
        self.mins.append(x if not self.mins else min(x, self.mins[-1]))

    def pop(self):
        self.stack.pop()
        self.mins.pop()

    def top(self):
        return self.stack[-1]

    def get_min(self):
        return self.mins[-1]

def run_ops(ops, args):
    s = MinStack()
    out = []
    for op, arg in zip(ops, args):
        if op == 'push':
            s.push(arg[0])
        elif op == 'pop':
            s.pop()
        elif op == 'top':
            out.append(s.top())
        elif op == 'get_min':
            out.append(s.get_min())
    return out

def eval_rpn(tokens):
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0]

def daily_temperatures(temps):
    out = [0] * len(temps)
    stack = []
    for i, t in enumerate(temps):
        while stack and temps[stack[-1]] < t:
            j = stack.pop()
            out[j] = i - j
        stack.append(i)
    return out

def next_greater(nums):
    out = [-1] * len(nums)
    stack = []
    for i, num in enumerate(nums):
        while stack and nums[stack[-1]] < num:
            out[stack.pop()] = num
        stack.append(i)
    return out

def remove_duplicates(s):
    stack = []
    for ch in s:
        if stack and stack[-1] == ch:
            stack.pop()
        else:
            stack.append(ch)
    return ''.join(stack)

def decode_string(s):
    stack = []
    current = ''
    count = 0
    for ch in s:
        if ch.isdigit():
            count = count * 10 + int(ch)
        elif ch == '[':
            stack.append((current, count))
            current = ''
            count = 0
        elif ch == ']':
            prev, k = stack.pop()
            current = prev + current * k
        else:
            current += ch
    return current

def validate_stack_sequences(pushed, popped):
    stack = []
    i = 0
    for value in pushed:
        stack.append(value)
        while stack and i < len(popped) and stack[-1] == popped[i]:
            stack.pop()
            i += 1
    return i == len(popped)

class MyQueue:
    def __init__(self):
        self.inbox = []
        self.outbox = []

    def push(self, x):
        self.inbox.append(x)

    def _transfer(self):
        if not self.outbox:
            while self.inbox:
                self.outbox.append(self.inbox.pop())

    def pop(self):
        self._transfer()
        return self.outbox.pop()

    def peek(self):
        self._transfer()
        return self.outbox[-1]

def run_ops(ops, args):
    q = MyQueue()
    out = []
    for op, arg in zip(ops, args):
        if op == 'push':
            q.push(arg[0])
        elif op == 'pop':
            out.append(q.pop())
        elif op == 'peek':
            out.append(q.peek())
    return out

from collections import deque

def max_sliding_window(nums, k):
    if not nums or k <= 0:
        return []
    dq = deque()
    out = []
    for i, num in enumerate(nums):
        while dq and dq[0] <= i - k:
            dq.popleft()
        while dq and nums[dq[-1]] < num:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            out.append(nums[dq[0]])
    return out

class MyCircularQueue:
    def __init__(self, k):
        self.buf = [0] * k
        self.capacity = k
        self.head = 0
        self.count = 0

    def enqueue(self, x):
        if self.count == self.capacity:
            return False
        self.buf[(self.head + self.count) % self.capacity] = x
        self.count += 1
        return True

    def dequeue(self):
        if self.count == 0:
            return False
        self.head = (self.head + 1) % self.capacity
        self.count -= 1
        return True

    def front(self):
        return -1 if self.count == 0 else self.buf[self.head]

    def rear(self):
        if self.count == 0:
            return -1
        return self.buf[(self.head + self.count - 1) % self.capacity]

def run_ops(k, ops, args):
    q = MyCircularQueue(k)
    out = []
    for op, arg in zip(ops, args):
        if op == 'enqueue':
            out.append(q.enqueue(arg[0]))
        elif op == 'dequeue':
            out.append(q.dequeue())
        elif op == 'front':
            out.append(q.front())
        elif op == 'rear':
            out.append(q.rear())
    return out

from collections import deque

def first_unique_stream(values):
    counts = {}
    q = deque()
    out = []
    for v in values:
        counts[v] = counts.get(v, 0) + 1
        q.append(v)
        while q and counts[q[0]] > 1:
            q.popleft()
        out.append(q[0] if q else -1)
    return out

from collections import deque

def recent_counts(pings):
    window = deque()
    out = []
    for t in pings:
        window.append(t)
        while window and window[0] < t - 3000:
            window.popleft()
        out.append(len(window))
    return out

