    root = build_tree(values)

    def walk(node):
        if not node:
            return (0, 0, 0)
        ln, ll, lt = walk(node.left)
        rn, rl, rt = walk(node.right)
        is_leaf = 1 if not node.left and not node.right else 0
        return (ln + rn + 1, ll + rl + is_leaf, lt + rt + node.val)

