    return {'nodes': nodes, 'leaves': leaves, 'total': total}

import heapq

def find_kth_largest(nums, k):
    heap = []
    for num in nums:
        heapq.heappush(heap, num)
        if len(heap) > k:
            heapq.heappop(heap)
    return heap[0]

import heapq

def last_stone_weight(stones):
    heap = [-s for s in stones]
    heapq.heapify(heap)
    while len(heap) > 1:
        first = -heapq.heappop(heap)
        second = -heapq.heappop(heap)
        if first != second:
            heapq.heappush(heap, -(first - second))
    return -heap[0] if heap else 0

import heapq

def merge_k_sorted(lists):
    heap = []
    for li, lst in enumerate(lists):
        if lst:
            heapq.heappush(heap, (lst[0], li, 0))
    out = []
    while heap:
        value, li, idx = heapq.heappop(heap)
        out.append(value)
        if idx + 1 < len(lists[li]):
            heapq.heappush(heap, (lists[li][idx + 1], li, idx + 1))
    return out

def group_sum(rows, key, value):
    out = {}
    for row in rows:
        out[row[key]] = out.get(row[key], 0) + row[value]
    return out

def group_stats(rows, key, value):
    buckets = {}
    for row in rows:
        buckets.setdefault(row[key], []).append(row[value])
    out = {}
    for group, values in buckets.items():
        out[group] = {
            'count': len(values),
            'sum': sum(values),
            'mean': round(sum(values) / len(values), 4),
            'min': min(values),
            'max': max(values),
        }
    return out

def inner_join(left, right, on):
    index = {}
    for row in right:
        index.setdefault(row[on], []).append(row)
    out = []
    for lrow in left:
        for rrow in index.get(lrow[on], []):
            merged = dict(lrow)
            merged.update(rrow)
            out.append(merged)
    return out

def left_join(left, right, on):
    index = {}
    right_cols = set()
    for row in right:
        index.setdefault(row[on], []).append(row)
        right_cols.update(row.keys())
    right_cols.discard(on)
    out = []
    for lrow in left:
        matches = index.get(lrow[on], [])
        if matches:
            for rrow in matches:
                merged = dict(lrow)
                merged.update(rrow)
                out.append(merged)
        else:
            merged = dict(lrow)
            for col in sorted(right_cols):
                merged.setdefault(col, None)
            out.append(merged)
    return out

def pivot(rows, index, column, value):
    out = {}
    for row in rows:
        out.setdefault(row[index], {})[row[column]] = row[value]
    return out

def drop_duplicates(rows, subset):
    seen = set()
    out = []
    for row in rows:
        key = tuple(row[col] for col in subset)
        if key not in seen:
            seen.add(key)
            out.append(row)
    return out

def fill_missing(rows, col, strategy):
    present = [r[col] for r in rows if r[col] is not None]
    if not present or strategy == 'zero':
        fill = 0
    elif strategy == 'mean':
        fill = round(sum(present) / len(present), 4)
    else:
        ordered = sorted(present)
        mid = len(ordered) // 2
        if len(ordered) % 2:
            fill = ordered[mid]
        else:
            fill = (ordered[mid - 1] + ordered[mid]) / 2
    for row in rows:
        if row[col] is None:
            row[col] = fill
    return rows

def top_n_per_group(rows, key, value, n):
    buckets = {}
    for i, row in enumerate(rows):
        buckets.setdefault(row[key], []).append((i, row))
    out = []
    for group in buckets:
        ordered = sorted(buckets[group], key=lambda pair: (-pair[1][value], pair[0]))
        out.extend(row for _, row in ordered[:n])
    return out

def rolling_mean(values, window):
    out = []
    total = 0.0
    for i, v in enumerate(values):
        total += v
        if i >= window:
            total -= values[i - window]
        if i >= window - 1:
            out.append(round(total / window, 4))
        else:
            out.append(None)
    return out

def one_hot(rows, col):
    categories = sorted({row[col] for row in rows})
    out = []
    for row in rows:
        new = {k: v for k, v in row.items() if k != col}
        for cat in categories:
            new[f'{col}_{cat}'] = 1 if row[col] == cat else 0
        out.append(new)
    return out

import math

def describe(values):
    if not values:
        return {}
    n = len(values)
    mean = sum(values) / n
    ordered = sorted(values)
    mid = n // 2
    median = ordered[mid] if n % 2 else (ordered[mid - 1] + ordered[mid]) / 2
    counts = {}
    for v in values:
        counts[v] = counts.get(v, 0) + 1
    best = max(counts.values())
    mode = min(v for v, c in counts.items() if c == best)
    if n < 2:
        variance = 0.0
    else:
        variance = sum((v - mean) ** 2 for v in values) / (n - 1)
    return {
        'mean': round(mean, 4),
        'median': round(median, 4),
        'mode': round(mode, 4),
        'variance': round(variance, 4),
        'std': round(math.sqrt(variance), 4),
    }

def percentile(values, p):
    if not values:
        return None
    ordered = sorted(values)
    if len(ordered) == 1:
        return round(float(ordered[0]), 4)
    pos = (len(ordered) - 1) * (p / 100)
    lo = int(pos)
    hi = min(lo + 1, len(ordered) - 1)
    frac = pos - lo
    return round(ordered[lo] + (ordered[hi] - ordered[lo]) * frac, 4)

def min_max_scale(values):
    if not values:
        return []
    lo, hi = min(values), max(values)
    if hi == lo:
        return [0.0] * len(values)
    span = hi - lo
    return [round((v - lo) / span, 4) for v in values]

import math

def pearson(x, y):
    n = len(x)
    if n < 2:
        return 0.0
    mx = sum(x) / n
    my = sum(y) / n
    cov = sum((a - mx) * (b - my) for a, b in zip(x, y))
    vx = sum((a - mx) ** 2 for a in x)
    vy = sum((b - my) ** 2 for b in y)
    if vx == 0 or vy == 0:
        return 0.0
    return round(cov / math.sqrt(vx * vy), 4)

def bin_values(values, bins):
    if not values or bins <= 0:
        return []
    lo, hi = min(values), max(values)
    if hi == lo:
        return [0] * len(values)
    width = (hi - lo) / bins
    out = []
    for v in values:
        idx = int((v - lo) / width)
        out.append(min(idx, bins - 1))
    return out

def weighted_average(rows, value, weight):
    num = 0.0
    den = 0.0
    for row in rows:
        v, w = row.get(value), row.get(weight)
        if v is None or w is None:
            continue
        num += v * w
        den += w
    return round(num / den, 4) if den else 0.0

def confusion_matrix(y_true, y_pred):
    tp = fp = tn = fn = 0
    for actual, pred in zip(y_true, y_pred):
        if pred == 1 and actual == 1:
            tp += 1
        elif pred == 1 and actual == 0:
            fp += 1
        elif pred == 0 and actual == 0:
            tn += 1
        else:
            fn += 1
    return {'tp': tp, 'fp': fp, 'tn': tn, 'fn': fn}

def roc_auc(y_true, y_score):
    pos = [s for t, s in zip(y_true, y_score) if t == 1]
    neg = [s for t, s in zip(y_true, y_score) if t == 0]
    if not pos or not neg:
        return 0.0
    wins = 0.0
    for p in pos:
        for n in neg:
            if p > n:
                wins += 1
            elif p == n:
                wins += 0.5
    return round(wins / (len(pos) * len(neg)), 4)

import math

def log_loss(y_true, y_prob):
    n = len(y_true)
    if n == 0:
        return 0.0
    eps = 1e-15
    total = 0.0
    for actual, p in zip(y_true, y_prob):
        p = min(max(p, eps), 1 - eps)
        total += -(actual * math.log(p) + (1 - actual) * math.log(1 - p))
    return round(total / n, 4)

def precision_at_k(y_true, y_score, k):
    n = len(y_true)
    if n == 0 or k <= 0:
        return 0.0
    order = sorted(range(n), key=lambda i: (-y_score[i], i))
    top = order[:min(k, n)]
    hits = sum(y_true[i] for i in top)
    return round(hits / len(top), 4)

def majority_baseline(y_true):
    n = len(y_true)
    if n == 0:
        return {}
    ones = sum(1 for y in y_true if y == 1)
    zeros = n - ones
    majority = 1 if ones > zeros else 0
    baseline = max(ones, zeros) / n
    return {
        'majority_class': majority,
        'baseline_accuracy': round(baseline, 4),
        'positive_rate': round(ones / n, 4),
    }

def fit_linear(x, y):
    n = len(x)
    if n < 2:
        return {'slope': 0.0, 'intercept': 0.0}
    mx = sum(x) / n
    my = sum(y) / n
    num = sum((a - mx) * (b - my) for a, b in zip(x, y))
    den = sum((a - mx) ** 2 for a in x)
    if den == 0:
        return {'slope': 0.0, 'intercept': 0.0}
    slope = num / den
    return {'slope': round(slope, 4), 'intercept': round(my - slope * mx, 4)}

def gradient_descent(x, y, lr, epochs):
    n = len(x)
    w = b = 0.0
    if n == 0:
        return {'w': 0.0, 'b': 0.0}
    for _ in range(epochs):
        dw = 0.0
        db = 0.0
        for xi, yi in zip(x, y):
            error = yi - (w * xi + b)
            dw += -2 * xi * error
            db += -2 * error
        w -= lr * (dw / n)
        b -= lr * (db / n)
    return {'w': round(w, 4), 'b': round(b, 4)}

import math

def sigmoid(z):
    if z >= 0:
        return 1 / (1 + math.exp(-z))
    exp_z = math.exp(z)
    return exp_z / (1 + exp_z)

def logistic_predict(x, w, b, threshold):
    probs = []
    labels = []
    for xi in x:
        p = sigmoid(w * xi + b)
        probs.append(round(p, 4))
        labels.append(1 if p >= threshold else 0)
    return {'probs': probs, 'labels': labels}

import math

def knn_predict(train_x, train_y, query, k):
    if not train_x:
        return -1
    dists = []
    for i, point in enumerate(train_x):
        d = math.sqrt(sum((a - b) ** 2 for a, b in zip(point, query)))
        dists.append((d, i))
    dists.sort()
    votes = {}
    for _, i in dists[:min(k, len(dists))]:
        label = train_y[i]
        votes[label] = votes.get(label, 0) + 1
    best = max(votes.values())
    return min(label for label, c in votes.items() if c == best)

def kmeans_step(points, centroids):
    if not centroids:
        return {'assignments': [], 'centroids': []}
    assignments = []
    for p in points:
        best = 0
        best_dist = abs(p - centroids[0])
        for j in range(1, len(centroids)):
            d = abs(p - centroids[j])
            if d < best_dist:
                best_dist = d
                best = j
        assignments.append(best)
    new_centroids = []
    for j, old in enumerate(centroids):
        members = [p for p, a in zip(points, assignments) if a == j]
        if members:
            new_centroids.append(round(sum(members) / len(members), 4))
        else:
            new_centroids.append(old)
    return {'assignments': assignments, 'centroids': new_centroids}

