import math

def entropy(labels):
    n = len(labels)
    if n == 0:
        return 0.0
    counts = {}
    for label in labels:
        counts[label] = counts.get(label, 0) + 1
    total = 0.0
    for c in counts.values():
        p = c / n
        if p > 0:
            total -= p * math.log2(p)
    return total

def information_gain(labels, split):
    n = len(labels)
    if n == 0:
        return {'parent_entropy': 0.0, 'weighted_child_entropy': 0.0,
                'information_gain': 0.0}
    parent = entropy(labels)
    groups = {}
    for label, g in zip(labels, split):
        groups.setdefault(g, []).append(label)
    weighted = sum(len(v) / n * entropy(v) for v in groups.values())
    return {
        'parent_entropy': round(parent, 4),
        'weighted_child_entropy': round(weighted, 4),
        'information_gain': round(parent - weighted, 4),
    }

import math

def cosine_similarity(a, b):
    if not a or not b:
        return 0.0
    dot = sum(x * y for x, y in zip(a, b))
    mag_a = math.sqrt(sum(x * x for x in a))
    mag_b = math.sqrt(sum(y * y for y in b))
    if mag_a == 0 or mag_b == 0:
        return 0.0
    return round(dot / (mag_a * mag_b), 4)

