    lo, hi = 1, x // 2
    ans = 1
    while lo <= hi:
        mid = (lo + hi) // 2
        sq = mid * mid
        if sq == x:
            return mid
        if sq < x:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

def min_eating_speed(piles, hours):
    def can_finish(speed):
        return sum((p + speed - 1) // speed for p in piles) <= hours
    lo, hi = 1, max(piles)
    while lo < hi:
        mid = (lo + hi) // 2
        if can_finish(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

