    while out and out[-1] is None:
        out.pop()
    return out


def min_depth(values):
    root = build_tree(values)
    if not root:
        return 0
    q = deque([(root, 1)])
    while q:
        node, depth = q.popleft()
        if not node.left and not node.right:
            return depth
        if node.left:
            q.append((node.left, depth + 1))
        if node.right:
            q.append((node.right, depth + 1))
    return 0

def rotate_matrix(matrix):
    n = len(matrix)
    for r in range(n):
        for c in range(r + 1, n):
            matrix[r][c], matrix[c][r] = matrix[c][r], matrix[r][c]
    for row in matrix:
        row.reverse()
    return matrix

def spiral_order(matrix):
    if not matrix or not matrix[0]:
        return []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    out = []
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            out.append(matrix[top][c])
        top += 1
        for r in range(top, bottom + 1):
            out.append(matrix[r][right])
        right -= 1
        if top <= bottom:
            for c in range(right, left - 1, -1):
                out.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:
            for r in range(bottom, top - 1, -1):
                out.append(matrix[r][left])
            left += 1
    return out

def set_zeroes(matrix):
    if not matrix or not matrix[0]:
        return matrix
    rows, cols = len(matrix), len(matrix[0])
    first_row_zero = any(matrix[0][c] == 0 for c in range(cols))
    first_col_zero = any(matrix[r][0] == 0 for r in range(rows))
    for r in range(1, rows):
        for c in range(1, cols):
            if matrix[r][c] == 0:
                matrix[r][0] = 0
                matrix[0][c] = 0
    for r in range(1, rows):
        for c in range(1, cols):
            if matrix[r][0] == 0 or matrix[0][c] == 0:
                matrix[r][c] = 0
    if first_row_zero:
        for c in range(cols):
            matrix[0][c] = 0
    if first_col_zero:
        for r in range(rows):
            matrix[r][0] = 0
    return matrix

def search_matrix(matrix, target):
    if not matrix or not matrix[0]:
        return False
    rows, cols = len(matrix), len(matrix[0])
    lo, hi = 0, rows * cols - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        value = matrix[mid // cols][mid % cols]
        if value == target:
            return True
        if value < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

def transpose(matrix):
    if not matrix or not matrix[0]:
        return []
    rows, cols = len(matrix), len(matrix[0])
    return [[matrix[r][c] for r in range(rows)] for c in range(cols)]

def single_number(nums):
    result = 0
    for num in nums:
        result ^= num
    return result

def count_set_bits(n):
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count

def counting_bits(n):
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i >> 1] + (i & 1)
    return dp

def missing_number_xor(nums):
    result = len(nums)
    for i, num in enumerate(nums):
        result ^= i ^ num
    return result

def longest_common_prefix(strs):
    if not strs:
        return ''
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ''
    return prefix

def compress(s):
    if not s:
        return ''
    parts = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        run = j - i
        parts.append(s[i])
        if run > 1:
            parts.append(str(run))
        i = j
    encoded = ''.join(parts)
    return encoded if len(encoded) < len(s) else s

def valid_palindrome_one_delete(s):
    def is_pal(lo, hi):
        while lo < hi:
            if s[lo] != s[hi]:
                return False
            lo += 1
            hi -= 1
        return True

    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return is_pal(left + 1, right) or is_pal(left, right - 1)
        left += 1
        right -= 1
    return True

def word_pattern(pattern, s):
    words = s.split()
    if len(pattern) != len(words):
        return False
    forward = {}
    backward = {}
    for ch, word in zip(pattern, words):
        if ch in forward and forward[ch] != word:
            return False
        if word in backward and backward[word] != ch:
            return False
        forward[ch] = word
        backward[word] = ch
    return True

def str_str(haystack, needle):
    if not needle:
        return 0
    n, m = len(haystack), len(needle)
    for i in range(n - m + 1):
        if haystack[i:i + m] == needle:
            return i
    return -1

def pivot_index(nums):
    total = sum(nums)
    left = 0
    for i, num in enumerate(nums):
        if left == total - left - num:
            return i
        left += num
    return -1

def subarrays_div_by_k(nums, k):
    seen = {0: 1}
    running = 0
    count = 0
    for num in nums:
        running = (running + num) % k
        count += seen.get(running, 0)
        seen[running] = seen.get(running, 0) + 1
    return count

def find_max_length(nums):
    first_seen = {0: -1}
    balance = 0
    best = 0
    for i, num in enumerate(nums):
        balance += 1 if num == 1 else -1
        if balance in first_seen:
            if i - first_seen[balance] > best:
                best = i - first_seen[balance]
        else:
            first_seen[balance] = i
    return best

def merge_sort(nums):
    if len(nums) <= 1:
        return list(nums)
    mid = len(nums) // 2
    left = merge_sort(nums[:mid])
    right = merge_sort(nums[mid:])
    out = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            out.append(left[i])
            i += 1
        else:
            out.append(right[j])
            j += 1
    out.extend(left[i:])
    out.extend(right[j:])
    return out

def h_index(citations):
    ordered = sorted(citations, reverse=True)
    h = 0
    for i, c in enumerate(ordered):
        if c >= i + 1:
            h = i + 1
        else:
            break
    return h

def my_pow(base, exp):
    negative = exp < 0
    e = -exp if negative else exp
    result = 1.0
    b = base
    while e:
        if e & 1:
            result *= b
        b *= b
        e >>= 1
    if negative:
        result = 1 / result
    return round(result, 6)

def plus_one(digits):
    out = list(digits)
    for i in range(len(out) - 1, -1, -1):
        if out[i] < 9:
            out[i] += 1
            return out
        out[i] = 0
    return [1] + out

def run_ops(capacity, ops, args):
    from collections import OrderedDict
    cache = OrderedDict()
    out = []
    for op, arg in zip(ops, args):
        if op == 'get':
            key = arg[0]
            if key in cache:
                cache.move_to_end(key)
                out.append(cache[key])
            else:
                out.append(-1)
        else:
            key, value = arg[0], arg[1]
            if key in cache:
                cache.move_to_end(key)
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)
    return out

def run_ops(ops, args):
    size = 1009
    buckets = [[] for _ in range(size)]
    out = []
    for op, arg in zip(ops, args):
        key = arg[0]
        bucket = buckets[key % size]
        if op == 'add':
            if key not in bucket:
                bucket.append(key)
        elif op == 'remove':
            if key in bucket:
                bucket.remove(key)
        else:
            out.append(key in bucket)
    return out

def run_ops(events):
    last_seen = {}
    out = []
    for timestamp, message in events:
        previous = last_seen.get(message)
        if previous is None or timestamp - previous >= 10:
            last_seen[message] = timestamp
            out.append(True)
        else:
            out.append(False)
    return out

def run_ops(ops, args):
    import bisect
    store = {}
    out = []
    for op, arg in zip(ops, args):
        if op == 'set':
            key, value, timestamp = arg[0], arg[1], arg[2]
            if key not in store:
                store[key] = ([], [])
            store[key][0].append(timestamp)
            store[key][1].append(value)
        else:
            key, timestamp = arg[0], arg[1]
            if key not in store:
                out.append('')
                continue
            times, values = store[key]
            i = bisect.bisect_right(times, timestamp)
            out.append(values[i - 1] if i else '')
    return out
